int[] bubbleSort(int[] nums) {
    int n = nums.length;
    for (int pass = 0; pass < n - 1; pass++) {
        boolean swapped = false;
        for (int j = 0; j < n - 1 - pass; j++) {   // the last pass values are already in place
            if (nums[j] > nums[j + 1]) {
                int t = nums[j];                    // swap the out-of-order neighbours
                nums[j] = nums[j + 1];
                nums[j + 1] = t;
                swapped = true;
            }
        }
        if (!swapped) break;                        // a pass with no swaps: sorted
    }
    return nums;
}

